    'Sending through SMTP as %s' => 'Verzenden via SMTP als %s',
    'Sending through %s' => 'Verzenden via %s',
    'Sending with PHP mail()' => 'Verzenden met PHP mail()',
    '1. Connection' => '1. Verbinding',
